import{ledgerFigure,compostFigure,biogasFigure,milkFigure}from './eco3-figures.js?v=20261023-physicscomplete01';
const film=(title,steps,render,note)=>({title,steps,render,note,duration:18});
export const eco3Films={
'eco3-carbon':film('Follow carbon between stores',['Photosynthesis transfers atmospheric carbon into plants.','Feeding transfers carbon to animals.','Plant respiration returns carbon dioxide.','Animal respiration returns carbon dioxide.','Death and waste supply decomposing material.','Decomposer respiration returns carbon dioxide.'],p=>ledgerFigure({ledger:'carbon',progress:p,moving:true}),'Selected carbon stores only; fossil fuels, oceans and other routes omitted. Moving signal traces material transfer, not measured travel time. Box counts are a fixed starting illustration, distinct from your editable account. Matter cycles; energy is not recycled identically.'),
'eco3-water':film('Follow water through changing stores',['Evaporation transfers liquid water to vapour.','Condensation forms liquid cloud droplets.','Precipitation supplies land with fresh water.','Runoff and groundwater return water to the sea.','Transpiration returns plant water to vapour.'],p=>ledgerFigure({ledger:'water',progress:p,moving:true}),'Selected combined stores; cloud water shown as droplets. Route marker is not a measured speed or a requirement for every molecule to follow one timed route. Fixed box counts show starting stores; your editable ledger is separate.'),
'eco3-decay':film('Follow loss from weighed organic material',['Begin with the original 100 g teaching sample.','Microorganisms break down organic material.','Products leave the weighed material.','Material remains conserved beyond the weighed boundary.'],p=>compostFigure({progress:p}),'Original illustrative 25°C moist, oxygen-available example: 6 g/day over 10 days, not a real measured or universal rate. Lost sample mass is not destroyed matter. Replaying resets the illustration; it does not collect evidence in your comparison.'),
'eco3-biogas':film('Follow an anaerobic digester',['Organic feed enters.','Microorganisms process material without oxygen.','Methane-containing biogas is collected.','Methane can be used as fuel.'],p=>biogasFigure(p),'Functional symbolic pathway, not an apparatus construction guide. Biogas is a mixture; the moving marker does not specify gas yield, travel speed or a universal rate.'),
'eco3-milk':film('Follow the lipase pH endpoint',['An equilibrated model starts alkaline.','Lipase releases fatty acids.','pH falls towards the defined endpoint.','Use the same endpoint for a timed comparison.'],p=>milkFigure({temp:35,elapsed:100*p}),'Original 35°C worked lipase model, endpoint mean 100 s. Linear pH interpolation and colour are illustrative, not an enzyme rate law. Fatty acids lower pH here; natural milk decay involves lactic acid. Not a bacterial cell count or a substitute for practical skills.')};
